//! Acknowledgements (FR4, research note 29): the licences of what a program is built from, as
//! the Acknowledgements window shows them. The editor holds its own list (generated by
//! `cargo about`); an engine gives its own with the `acknowledgements` operation, under the
//! capability of that name (spec section 5.3), and one without it shows "no list given".
//!
//! A list is grouped by licence: each licence's text once, with the packages under it. It comes
//! from the other side, so reading it never panics and every size is bounded ([`Acknowledgements::bounded`]):
//! malformed groups and packages are skipped, long texts cut, and anything past the limits left
//! out with a note that says so.

use serde::{Deserialize, Serialize};

use crate::de::{lenient_vec, null_as_default};

/// The most licence groups a list keeps.
pub const MAX_GROUPS: usize = 512;
/// The most packages a group keeps.
pub const MAX_PACKAGES: usize = 4096;
/// The longest licence text kept (characters); a longer one is cut, saying so.
pub const MAX_TEXT_CHARS: usize = 256 * 1024;
/// The most characters a whole list keeps, every text together.
pub const MAX_TOTAL_CHARS: usize = 8 * 1024 * 1024;
/// The longest name, version, address or licence id kept (characters).
pub const MAX_FIELD_CHARS: usize = 512;

/// One program's licences.
#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[serde(default)]
pub struct Acknowledgements {
    #[serde(deserialize_with = "lenient_vec")]
    pub groups: Vec<LicenceGroup>,
    /// What [`Acknowledgements::bounded`] left out, in words; empty when nothing was.
    #[serde(deserialize_with = "null_as_default", skip_serializing_if = "String::is_empty")]
    pub note: String,
}

/// A licence and the packages under it.
#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[serde(default)]
pub struct LicenceGroup {
    /// The licence's SPDX id (`MIT`, `Apache-2.0`) or name.
    #[serde(deserialize_with = "null_as_default")]
    pub licence: String,
    /// Its name as people say it ("MIT License"); may be empty.
    #[serde(deserialize_with = "null_as_default", skip_serializing_if = "String::is_empty")]
    pub name: String,
    /// The full text, once for every package under it.
    #[serde(deserialize_with = "null_as_default")]
    pub text: String,
    #[serde(deserialize_with = "lenient_vec")]
    pub packages: Vec<Package>,
}

/// A package under a licence.
#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[serde(default)]
pub struct Package {
    #[serde(deserialize_with = "null_as_default")]
    pub name: String,
    #[serde(deserialize_with = "null_as_default", skip_serializing_if = "String::is_empty")]
    pub version: String,
    /// Where its source is (a repository, a registry page); may be empty.
    #[serde(deserialize_with = "null_as_default", skip_serializing_if = "String::is_empty")]
    pub url: String,
}

fn cut(s: &mut String, max: usize) -> bool {
    match s.char_indices().nth(max) {
        Some((at, _)) => {
            s.truncate(at);
            true
        }
        None => false,
    }
}

impl Acknowledgements {
    /// Read a list from the other side: never fails (a malformed one is empty), and bounded.
    pub fn from_value(v: serde_json::Value) -> Acknowledgements {
        serde_json::from_value::<Acknowledgements>(v).unwrap_or_default().bounded()
    }

    /// The list within the limits: groups without a licence or packages dropped, long fields
    /// and texts cut, groups and packages past the limits left out, the whole under
    /// [`MAX_TOTAL_CHARS`]; `note` says what went.
    pub fn bounded(mut self) -> Acknowledgements {
        let mut cuts = Vec::new();
        self.groups.retain(|g| !g.licence.trim().is_empty() && !g.packages.is_empty());
        if self.groups.len() > MAX_GROUPS {
            cuts.push(format!("{} licences past the first {MAX_GROUPS}", self.groups.len() - MAX_GROUPS));
            self.groups.truncate(MAX_GROUPS);
        }
        let mut total = 0usize;
        let mut kept = 0usize;
        for g in &mut self.groups {
            cut(&mut g.licence, MAX_FIELD_CHARS);
            cut(&mut g.name, MAX_FIELD_CHARS);
            if cut(&mut g.text, MAX_TEXT_CHARS) {
                g.text.push_str("\n\n[… cut: the text is longer than the list keeps]");
            }
            g.packages.retain(|p| !p.name.trim().is_empty());
            if g.packages.len() > MAX_PACKAGES {
                cuts.push(format!("{} packages under {}", g.packages.len() - MAX_PACKAGES, g.licence));
                g.packages.truncate(MAX_PACKAGES);
            }
            for p in &mut g.packages {
                cut(&mut p.name, MAX_FIELD_CHARS);
                cut(&mut p.version, MAX_FIELD_CHARS);
                cut(&mut p.url, MAX_FIELD_CHARS);
            }
            let size = g.text.chars().count() + g.packages.iter().map(|p| p.name.len() + p.version.len() + p.url.len()).sum::<usize>();
            if total + size > MAX_TOTAL_CHARS {
                break;
            }
            total += size;
            kept += 1;
        }
        if kept < self.groups.len() {
            cuts.push(format!("{} licences past the list's size", self.groups.len() - kept));
            self.groups.truncate(kept);
        }
        self.groups.retain(|g| !g.packages.is_empty());
        cut(&mut self.note, MAX_FIELD_CHARS);
        if !cuts.is_empty() {
            let said = format!("Left out: {}.", cuts.join("; "));
            self.note = if self.note.is_empty() { said } else { format!("{} {said}", self.note) };
        }
        self
    }

    /// A list `cargo about` made with PlumCraft's template (`crates/editor-core/acknowledgements/about.hbs`,
    /// research note 29), as an engine built with the Rust SDK gives it: packages with no
    /// `source` (the workspace's own crates) are left out, then the list is bounded.
    pub fn from_cargo_about(text: &str) -> Acknowledgements {
        let mut v: serde_json::Value = serde_json::from_str(text).unwrap_or(serde_json::Value::Null);
        if let Some(groups) = v.get_mut("groups").and_then(serde_json::Value::as_array_mut) {
            for g in groups {
                if let Some(p) = g.get_mut("packages").and_then(serde_json::Value::as_array_mut) {
                    p.retain(|p| p.get("source").is_some_and(|s| !s.is_null()));
                }
            }
        }
        Acknowledgements::from_value(v)
    }

    /// How many packages the list names.
    pub fn package_count(&self) -> usize {
        self.groups.iter().map(|g| g.packages.len()).sum()
    }
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::*;

    #[test]
    fn a_list_reads_and_is_bounded() {
        let a = Acknowledgements::from_value(json!({"groups": [
            {"licence": "MIT", "name": "MIT License", "text": "Permission is hereby granted", "packages": [{"name": "serde", "version": "1.0.0", "url": "https://x"}, {"name": ""}, 7]},
            {"licence": "", "text": "x", "packages": [{"name": "nameless licence"}]},
            {"licence": "Zlib", "text": "z", "packages": []},
            "junk"
        ]}));
        assert_eq!(a.groups.len(), 1);
        assert_eq!(a.groups[0].packages.len(), 1, "a package with no name and junk are skipped");
        assert_eq!(a.package_count(), 1);
        assert!(a.note.is_empty());
        // too long a text is cut, saying so; too many groups are left out, saying so
        let big = "x".repeat(MAX_TEXT_CHARS + 10);
        let groups: Vec<_> = (0..MAX_GROUPS + 3)
            .map(|k| json!({"licence": format!("L{k}"), "text": if k == 0 { big.clone() } else { "t".into() }, "packages": [{"name": "p"}]}))
            .collect();
        let a = Acknowledgements::from_value(json!({"groups": groups}));
        assert_eq!(a.groups.len(), MAX_GROUPS);
        assert!(a.groups[0].text.ends_with("longer than the list keeps]"));
        assert!(a.note.contains("3 licences past the first 512"), "{}", a.note);
        // not a list at all: empty
        assert_eq!(Acknowledgements::from_value(json!("hello")), Acknowledgements::default());
        // cargo about's output: the workspace's own crates (no source) are left out
        let made = r#"{"made_by": "cargo about", "groups": [
            {"licence": "MIT", "name": "MIT License", "text": "M", "packages": [{"name": "mine", "version": "1", "url": null, "source": null}, {"name": "serde", "version": "1.0.0", "url": "https://github.com/serde-rs/serde", "source": "registry+https://github.com/rust-lang/crates.io-index"}]},
            {"licence": "Apache-2.0", "name": "Apache License 2.0", "text": "A", "packages": [{"name": "mine", "version": "1", "url": null, "source": null}]}
        ]}"#;
        let a = Acknowledgements::from_cargo_about(made);
        assert_eq!(a.groups.len(), 1);
        assert_eq!(a.groups[0].packages[0].name, "serde");
        assert_eq!(Acknowledgements::from_cargo_about("not json"), Acknowledgements::default());
    }
}
